<script setup>
import {computed,inject,onMounted,ref,watch} from 'vue'
import {api} from '../api.js'
import CalibrationMetrics from '../components/CalibrationMetrics.vue'
import EvidenceDetails from '../components/EvidenceDetails.vue'
import CalibrationJudgmentForm from '../components/CalibrationJudgmentForm.vue'
import CalibrationIssues from '../components/CalibrationIssues.vue'
import CalibrationDataRepair from '../components/CalibrationDataRepair.vue'
import {newJudgment,labelFor,protocolLabels,dimensionLabels} from '../calibration-presentation.js'
const work=inject('workspace'),cal=inject('calibration'),{state}=cal
const steps=['准备样本','评分细则','独立标注','AI 评分','看分歧','修改与复测','保留验证','保存结论','问题与修复']
const labels=dimensionLabels
const error=ref(''),sourceHistory=ref([]),sourceRunId=ref(''),sourceView=ref(null)
const name=ref('电商问答评测校准'),sampleJson=ref('[]'),groupConfirmed=ref(false)
const priority=ref('优先减少关键错误放行，同时观察错误拒绝与评测覆盖率'),cost=ref('记录请求数与 usage；未获得费用时显示未知')
const definition=ref(null),selectedSample=ref(''),source=ref('HUMAN'),seen=ref(false),seenPeer=ref(false)
const annotationValue=ref(newJudgment()),adjudicationValue=ref(newJudgment())
const importJson=ref('[]'),adjudicationSample=ref(''),adjudicationReason=ref('')
const citationMode=ref('FRAGMENT_IDS')
const protocolName=ref('基础评分 · 固定回答与依据'),variant=ref('J1'),hypothesis=ref('评分对应的表现与双层证据能帮助核查判定依据。'),parentId=ref(''),exampleIds=ref([]),addendum=ref('')
const protocolId=ref(''),repetitions=ref(1),budget=ref(20),runId=ref(''),baselineId=ref(''),candidateId=ref('')
const inspected=ref(''),hypothesisCauses=ref([]),hypothesisReason=ref('')
const baseProtocol=ref(''),candidateProtocol=ref(''),validationReason=ref(''),validationRepetitions=ref(1),validationBudget=ref(20)
const baselineSession=ref(''),candidateSession=ref(''),decision=ref('KEEP_BASELINE'),conclusionReason=ref(''),conclusionConfirmed=ref(false)
const causeLabels={RUBRIC_AMBIGUOUS:'标准含糊',REFERENCE_ERROR:'题目或参照有误',MISSED_CONDITION:'评分 AI 漏看条件',UNSUPPORTED_INFERENCE:'评分 AI 无依据推断',REASONABLE_REFUSAL:'误判合理拒答',VERBOSITY_PREFERENCE:'偏好冗长',CONTEXT_MISREAD:'上下文读取不足'}
const calibrationCount=computed(()=>state.dataset?.samples.filter(s=>s.partition==='CALIBRATION').length||0)
const holdoutCount=computed(()=>state.dataset?.samples.filter(s=>s.partition==='HOLDOUT').length||0)
const protocols=computed(()=>state.history.protocols.filter(p=>p.dataset_id===state.dataset?.dataset_id&&p.rubric_id===state.rubric?.rubric_id))
const runs=computed(()=>state.history.runs.filter(r=>r.dataset_id===state.dataset?.dataset_id&&r.rubric_id===state.rubric?.rubric_id))
const pendingBudget=computed(()=>calibrationCount.value*repetitions.value)
const finalBudget=computed(()=>holdoutCount.value*validationRepetitions.value*2)
const ready=computed(()=>!!state.dataset&&!!state.rubric)
const sessionReady=computed(()=>work.state.session?.text_connection_status==='READY'&&work.state.session?.credential_status==='PRESENT')
const actorSamples=computed(()=>state.dataset?.samples||[])
const detailSample=computed(()=>state.dataset?.samples.find(s=>s.sample_id===inspected.value))
const detailResults=computed(()=>state.run?.results.filter(r=>r.sample_id===inspected.value)||[])
const adjudicationRecord=computed(()=>state.dataset?.samples.find(s=>s.sample_id===adjudicationSample.value))
const parse=async fn=>{error.value='';try{await fn()}catch(e){error.value=e.message||'请检查填写内容'}}
function newAnnotation(){annotationValue.value=newJudgment();seen.value=false;seenPeer.value=false}
watch(()=>state.blind,v=>{if(v)newAnnotation()})
watch(()=>state.actor,()=>{state.blind=null;state.run=null;state.comparison=null;state.annotationRecords=null;state.issues=[];adjudicationSample.value='';cal.persist()})
watch(()=>state.rubric,v=>{if(v)definition.value=JSON.parse(JSON.stringify(Object.fromEntries(['name','dimensions','critical_errors','applicable_scope','rules'].map(k=>[k,v[k]]))))},{immediate:true})
watch(()=>work.state.session?.provider_session_id,id=>{baselineSession.value=id||'';candidateSession.value=id||''},{immediate:true})
watch(()=>state.step,step=>{
  if(step===6&&variant.value==='J1'){variant.value='J2';protocolName.value='增加证据核对 · 修改与复测';parentId.value=protocols.value.find(p=>p.variant==='J1')?.protocol_id||'';hypothesis.value='增加逐项证据核验，观察关键错误漏检与错误拒绝是否变化。'}
})
onMounted(()=>parse(async()=>{
  await cal.refresh();sourceHistory.value=await api.get('/retrieval-history')
  if(!definition.value)definition.value=await api.get('/calibration/template')
}))
async function loadSource(){await cal.act('读取历史冻结回答',async()=>{sourceView.value=await api.get('/retrieval-runs/'+sourceRunId.value)})}
function selectSource(caseId){
  if(!state.selections.some(s=>s.run_id===sourceRunId.value&&s.case_id===caseId))state.selections.push({run_id:sourceRunId.value,case_id:caseId,
    group_id:'question-'+caseId,partition:'CALIBRATION',origin:'UNKNOWN',scenario:'',diagnostic:false,source_viewer:state.actor})
}
async function freezeDataset(){await parse(async()=>{
  const samples=JSON.parse(sampleJson.value);if(!Array.isArray(samples))throw Error('样本导入须为 JSON 数组。')
  await cal.createDataset({name:name.value,samples,selections:state.selections,group_review_confirmed:groupConfirmed.value,priority_metric:priority.value,acceptable_cost:cost.value})
})}
async function openSample(){await cal.openBlind(selectedSample.value)}
async function submitAnnotation(value){await parse(async()=>{await cal.annotate({source:source.value,seen_machine:seen.value,seen_peer:seenPeer.value,judgment:value});await cal.loadAnnotations()})}
async function importLabels(){await parse(async()=>{const result=await cal.importAnnotations(JSON.parse(importJson.value));if(result)error.value=`导入：${result.results.filter(r=>r.status==='SAVED').length} 条保存，${result.results.filter(r=>r.status==='REJECTED').length} 条被拒绝。`})}
function pickAdjudication(record){adjudicationSample.value=record.sample_id;adjudicationValue.value=JSON.parse(JSON.stringify(record.judgment));adjudicationReason.value=''}
async function adjudicate(value){await parse(async()=>{await cal.adjudicate({dataset_id:state.dataset.dataset_id,sample_id:adjudicationSample.value,rubric_id:state.rubric.rubric_id,
  annotation_ids:state.annotationRecords.references[adjudicationSample.value].annotation_ids,adjudicator_id:state.actor,source:source.value,
  judgment:value,reason:adjudicationReason.value});adjudicationSample.value=''})}
function trackIssue(){state.issueDraft={run_id:state.run.run.run_id,sample_id:inspected.value,title:detailSample.value.question.slice(0,200)};cal.go(9)}
async function createProtocol(){await cal.createProtocol({name:protocolName.value,variant:variant.value,change_hypothesis:hypothesis.value,
  parent_protocol_id:parentId.value||null,example_sample_ids:exampleIds.value,prompt_addendum:addendum.value,citation_mode:citationMode.value});protocolId.value=state.protocol?.protocol_id||''}
async function runJudge(){const result=await cal.run({protocol_id:protocolId.value,repetitions:repetitions.value,budget:budget.value});if(result){runId.value=result.run_id;cal.go(5)}}
async function inspect(id){inspected.value=id;hypothesisCauses.value=[];hypothesisReason.value=''}
async function exportReport(id){await cal.act('导出冻结报告',async()=>{
  const result=await cal.export(id)
  for(const [extension,text] of [['md',result.markdown],['json',JSON.stringify(result.json,null,2)]]){
    const url=URL.createObjectURL(new Blob([text],{type:extension==='json'?'application/json':'text/markdown;charset=utf-8'}))
    const link=document.createElement('a');link.href=url;link.download=`calibration-${id}.${extension}`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)
  }
})}
</script>
<template>
  <div class="calibration-page">
    <p class="note">进阶入口：平台维护者负责基础练习标准与可信度。普通学习者无需先建立自己的 Judge 研究，可先完成证据判断练习。</p>
    <div class="page-heading"><div><div class="eyebrow">EVALUATOR CALIBRATION</div><h1>评测校准</h1><p>固定回答，建立独立参照，检查 AI 评分是否合理，并记录问题怎样被修复。</p></div><span class="pill">研究状态以真实参照和验证记录为准</span></div>
    <details class="panel"><summary>第一次用：评分标准和评测校准是做什么的？</summary><p>评分标准说明什么算好回答，例如事实有依据、没有漏掉必要条件。评测校准检查评分模型能否按这套标准判断：先由人独立判断固定回答，再与模型评分对照，找出误判并修订。</p><p>这里重评已有回答。修改客服、让它重新回答并检查效果，请使用主实验。看过模型判定之后再做人评属于复核，不能当作独立盲评。</p></details>
    <section class="panel cal-overview"><div class="two-column"><label>样本集<select :value="state.dataset?.dataset_id||''" :disabled="!!work.state.busy" @change="cal.act('打开冻结样本集',()=>cal.openDataset($event.target.value))"><option value="" disabled>选择或建立样本集</option><option v-for="d in state.history.datasets" :key="d.dataset_id" :value="d.dataset_id">{{d.name}} · {{d.calibration_count}} 校准 / {{d.holdout_count}} 保留</option></select></label><label>评分细则版本<select :value="state.rubric?.rubric_id||''" :disabled="!!work.state.busy" @change="state.rubric=state.history.rubrics.find(r=>r.rubric_id===$event.target.value);state.blind=null;state.run=null;state.comparison=null;cal.persist()"><option value="" disabled>请保存初始标准</option><option v-for="r in state.history.rubrics" :key="r.rubric_id" :value="r.rubric_id">{{r.name}} · {{r.rubric_id.slice(0,8)}}</option></select></label></div><p v-if="state.dataset" class="muted">{{calibrationCount}} 份校准回答 · {{holdoutCount}} 份保留回答 · 工作流隔离。开发者可访问本地内容，制作和标注曝光须如实记录。</p></section>
    <div class="cal-purpose-grid"><article><strong>先确认标准</strong><p>人先定义什么算好回答，再按同一细则核对 AI 评分。</p></article><article><strong>分别看两件事</strong><p>回答有没有编造，和用户问题是否解决，分别记录。</p></article><article><strong>最后验证修复</strong><p>把问题、修改和新一轮结果关联，保留未改善的结论。</p></article></div>
    <nav class="cal-steps" aria-label="校准步骤"><button v-for="(label,index) in steps" :key="label" :class="{active:state.step===index+1}" :disabled="!!work.state.busy" @click="cal.go(index+1)"><span>{{index+1}}</span>{{label}}</button></nav>
    <p v-if="error" class="note warning" role="alert">{{error}}</p>
    <fieldset class="cal-fieldset" :disabled="!!work.state.busy">
    <template v-if="state.step===1">
      <section class="panel"><h2>准备固定问题—回答—证据</h2><p>从已有运行复制不可变快照，或导入同结构样本。这里只重评已有回答。历史政策缺失时保留缺失标记。</p><div class="button-row"><select v-model="sourceRunId" aria-label="历史 RAG 运行"><option value="">选择已有 RAG 运行</option><option v-for="r in sourceHistory" :key="r.run_id" :value="r.run_id">{{r.name}} · {{r.run_id.slice(0,8)}} · {{labelFor(r.status)}}</option></select><button class="secondary" :disabled="!sourceRunId" @click="loadSource">查看可加入的回答</button></div><div v-if="sourceView"><div v-for="a in sourceView.run.answer_results" :key="a.case_id" class="cal-source"><p>{{a.turn_evidence[0]?.question}}</p><p class="muted">{{a.turn_evidence[0]?.response}}</p><button class="secondary" :disabled="!a.turn_evidence[0]?.response" @click="selectSource(a.case_id)">加入待冻结选择</button></div><p v-if="!sourceView.run.answer_results.length" class="empty">此运行没有实际回答。请选择已生成回答的历史运行。</p></div>
        <div v-for="(s,index) in state.selections" :key="s.run_id+s.case_id" class="cal-source"><strong>{{s.case_id}}</strong><div class="cal-form-grid"><label>同源分组<input v-model="s.group_id" /></label><label>用途<select v-model="s.partition"><option value="CALIBRATION">校准</option><option value="HOLDOUT">保留验证</option></select></label><label>来源<select v-model="s.origin"><option value="UNKNOWN">未知，尚未确认</option><option value="CONSTRUCTED">人工构造</option><option value="ACTUAL">实际使用</option><option value="AI_GENERATED">AI 生成</option></select></label><label>场景<input v-model="s.scenario" placeholder="多条件、知识缺失等" /></label></div><label class="check"><input v-model="s.diagnostic" type="checkbox" />这是植入错误的诊断回答</label><button class="text-button" @click="state.selections.splice(index,1)">移除此选择</button></div>
        <details class="evidence"><summary>JSON 导入固定样本</summary><p>每条包含 group_id、partition、question、answer、context、retrieved_evidence、reference_policy、reference_complete、origin、scenario；证据含 evidence_id、document_id、text。近义题及同源模板请使用相同 group_id 或 template_id。</p><textarea v-model="sampleJson" rows="10" aria-label="样本 JSON" spellcheck="false" /><p>完整政策须是当时的快照；不要把今天的知识当作历史依据。改写及模板分组需要人工确认，系统会拦截明显跨集重复。</p></details>
        <label>样本集名称<input v-model="name" /></label><label>优先指标<textarea v-model="priority" rows="2" /></label><label>可接受代价与约束<textarea v-model="cost" rows="2" /></label><label class="check"><input v-model="groupConfirmed" type="checkbox" />已核对近重复与同源模板分组，确认用途和类别分布。冻结后新增样本需建新集合。</label><button class="primary" :disabled="!groupConfirmed" @click="freezeDataset">冻结样本集 →</button>
      </section>
      <section v-if="state.dataset" class="panel"><h2>冻结内容</h2><table class="cal-table"><thead><tr><th>问题</th><th>分组／用途</th><th>来源</th><th>政策</th></tr></thead><tbody><tr v-for="s in state.dataset.samples" :key="s.sample_id"><td>{{s.question}}</td><td>{{s.group_id}} · {{labelFor(s.partition)}}</td><td>{{labelFor(s.origin)}} {{s.diagnostic?'· 诊断':''}}</td><td>{{s.reference_complete?'声明完整，需核对':'未确认完整'}}</td></tr></tbody></table></section>
    </template>
    <section v-else-if="state.step===2" class="panel"><h2>定义具体的评分细则</h2><p>初始电商模板尚未经过校准。更改尺度或通过标准会创建新的评分细则版本，相关题需重新标注。</p><template v-if="definition"><label>版本名称<input v-model="definition.name" /></label><label>适用范围<textarea v-model="definition.applicable_scope" rows="2" /></label><section v-for="(d,key) in definition.dimensions" :key="key" class="cal-rubric"><h3>{{d.label}}</h3><div class="cal-form-grid"><label v-for="level in ['0','1','2']" :key="level">{{level}} 分对应的表现<textarea v-model="d.anchors[level]" rows="2" /></label><label>通过最低分<input v-model.number="definition.rules.minimum_scores[key]" type="number" min="0" max="2" /></label></div><div class="two-column"><label>正例<input v-model="d.positive" /></label><label>反例<input v-model="d.negative" /></label><label>边界案例<textarea v-model="d.boundary" rows="2" /></label><label>适用条件<textarea v-model="d.applicability" rows="2" /></label></div></section><label v-for="(text,key) in definition.critical_errors" :key="key">关键错误 · {{key}}<input v-model="definition.critical_errors[key]" /></label><p class="note">严重错误 → 不合格；证据不足 → 待裁决；初始规则中仅“下一步可用性”可判不适用。初始事实与条件须 2 分，其他适用维度至少 1 分。</p><details class="evidence"><summary>判定规则完整配置</summary><pre>{{JSON.stringify(definition.rules,null,2)}}</pre></details><button class="primary" @click="cal.saveRubric({definition,parent_rubric_id:state.rubric?.rubric_id||null})">保存新的标准版本</button></template></section>
    <template v-else-if="state.step===3">
      <p v-if="!ready" class="empty">先冻结样本集并保存评分细则。</p>
      <template v-else><section class="panel"><h2>独立标注 · 隐藏机评</h2><p>本页隐藏机器分数、理由和 Agent 版本。是否见过机评需如实填写；AI 和 Codex 记录不计入人工参照。</p><div class="cal-form-grid"><label>标注者标识<input v-model="state.actor" maxlength="100" /></label><label>记录来源<select v-model="source"><option value="HUMAN">真实人工</option><option value="AI">AI 建议</option><option value="CODEX">Codex 功能验收</option></select></label><label>选择固定样本<select v-model="selectedSample"><option value="">选择问题</option><option v-for="s in actorSamples" :key="s.sample_id" :value="s.sample_id">{{s.question}} · {{labelFor(s.partition)}}</option></select></label></div><button class="primary" :disabled="!selectedSample||!state.actor.trim()||!!state.validation" @click="openSample">打开盲标样本</button><p v-if="state.validation" class="note">候选已锁定，人工参照已冻结。继续研究请建立新样本集。</p></section>
        <section v-if="state.blind" class="panel cal-blind"><h2>{{state.blind.sample.question}}</h2><p v-if="state.blind.prior_machine_exposure" class="note warning">此标注者有机评曝光记录。本次可保存复核，但不会进入独立人工参照分母。</p><div v-if="state.blind.sample.context.length"><h3>多轮上下文</h3><p v-for="(m,index) in state.blind.sample.context" :key="index">{{m.role}}：{{m.content}}</p></div><h3>固定实际回答</h3><p class="cal-answer">{{state.blind.sample.answer}}</p><h3>必要事实与约束</h3><p v-for="(fact,index) in state.blind.sample.expected_facts" :key="index">{{fact}}</p><div class="two-column"><div><h3>当时检索到的片段 · 检查忠实性</h3><article v-for="e in state.blind.sample.retrieved_evidence" :key="e.evidence_id" class="cal-evidence"><strong>{{e.evidence_id}}</strong><p>{{e.text}}</p></article><p v-if="!state.blind.sample.retrieved_evidence.length" class="empty">没有检索片段。</p></div><div><h3>完整参考政策 · 检查任务完成</h3><p v-if="!state.blind.sample.reference_complete" class="note warning">参考政策不完整，必要信息不足时应待裁决。</p><article v-for="e in state.blind.sample.reference_policy" :key="e.evidence_id" class="cal-evidence"><strong>{{e.evidence_id}}</strong><p>{{e.text}}</p></article></div></div>
          <CalibrationJudgmentForm v-model="annotationValue" :sample="state.blind.sample" :rubric="state.rubric" :fragments="state.blind.fragments" @submit="submitAnnotation">
            <label class="check"><input v-model="seen" type="checkbox" />本人曾看过此回答的机评分数或理由</label><label class="check"><input v-model="seenPeer" type="checkbox" />本人已看过他人标注或共同讨论过此题的判断</label><p v-if="state.blind.prior_peer_exposure" class="note warning">已记录此标注者看过本题他人意见。本次改标保存为复核，不计为新的独立盲标。</p><p class="muted">记录来源：{{labelFor(source)}}。AI 和 Codex 的判断不会作为独立人工参照。</p>
          </CalibrationJudgmentForm>
        </section>
        <section v-if="!state.blind" class="panel"><h2>第二位标注者与裁决</h2><p>每位标注者先用自己的标识独立提交，再看其他人的意见。未提交题目的评分与裁决依据会隐藏。</p>
          <button class="secondary" @click="cal.act('读取人工分歧',cal.loadAnnotations)">查看标注进度与分歧</button>
          <template v-if="state.annotationRecords"><p class="note">本人已标 {{state.annotationRecords.own_submitted_count}} / {{state.annotationRecords.sample_count}} 题；尚未标注的 {{state.annotationRecords.hidden_sample_count}} 题隐藏他人判断。</p>
            <div class="cal-progress-list"><p v-for="p in state.annotationRecords.progress" :key="p.annotator_id">{{p.annotator_id}}：已提交 {{p.submitted_count}} 题，独立人工 {{p.independent_human_count}} 题</p></div>
            <p>可查看题目的人工判定一致数：{{state.annotationRecords.human_agreement.binary_agreement_before_adjudication.numerator}} / {{state.annotationRecords.human_agreement.binary_agreement_before_adjudication.denominator}}（零分母不可计算）</p>
            <div v-for="a in state.annotationRecords.annotations" :key="a.annotation_id" class="cal-source"><p><strong>{{state.dataset.samples.find(s=>s.sample_id===a.sample_id)?.question}}</strong></p><p>{{a.annotator_id}} · {{labelFor(a.source)}} · {{a.independent?'独立':'有曝光或非人工'}} · {{labelFor(a.judgment.verdict)}}</p><p class="muted">{{a.judgment.reason}}</p><p><span v-for="(d,key) in a.judgment.dimensions" :key="key" class="pill">{{labels[key]}}：{{d.score==='INSUFFICIENT'?'证据不足':d.score==='NA'?'不适用':d.score}} </span></p><button v-if="state.annotationRecords.references[a.sample_id].state==='DISAGREEMENT'" class="secondary" @click="pickAdjudication(a)">打开表单裁决</button></div>
            <section v-if="adjudicationRecord" class="cal-adjudication"><h3>裁决：{{adjudicationRecord.question}}</h3><p>下面以选中的原标注为起点，请核对分数与原文，并说明为什么采用此判断。原标注会继续保留。</p><label>裁决理由<textarea v-model="adjudicationReason" rows="3" /></label><CalibrationJudgmentForm v-model="adjudicationValue" :sample="adjudicationRecord" :rubric="state.rubric" :disabled="!adjudicationReason.trim()" submit-label="保存人工分歧裁决" @submit="adjudicate" /></section>
          </template>
          <details class="evidence"><summary>高级：导入离线标注 JSON</summary><p>保留标注者、真实来源、曝光和时间；导入不会把曝光复核转成独立人工参照。</p><textarea v-model="importJson" rows="8" aria-label="标注导入 JSON" /><button class="secondary" @click="importLabels">导入标注</button></details>
        </section>
      </template>
    </template>
    <template v-else-if="state.step===4||state.step===6">
      <p v-if="!ready" class="empty">先冻结样本集并保存评分细则。</p><template v-else><section class="panel"><h2>{{state.step===6?'声明修改假设并复测':'保存 AI 评分方法'}}</h2><p>评分细则规定什么算好回答；评分方法告诉 AI 怎么检查。基础版按细则评分，核对版额外检查依据，示例版加入真人确认的边界例。每次保存创建独立版本。</p><p v-if="!sessionReady" class="note warning">请到模型配置页保存并测试连接。</p><button v-if="!sessionReady" class="secondary" @click="work.go('setup')">配置模型</button><div class="cal-form-grid"><label>协议名称<input v-model="protocolName" /></label><label>评分方式<select v-model="variant"><option value="J1">基础评分</option><option value="J2">增加证据核对</option><option value="J3">加入人工边界示例</option></select></label><label>父协议<select v-model="parentId"><option value="">初始协议</option><option v-for="p in protocols" :key="p.protocol_id" :value="p.protocol_id">{{p.name}}</option></select></label></div><label>引用方式<select v-model="citationMode"><option value="FRAGMENT_IDS">选择原文片段编号（新版）</option><option value="SHORT_IDS">短片段编号 · 与主评测及 LangSmith 共用</option><option value="VERBATIM">逐字抄写原文（兼容旧版）</option></select></label><p class="muted">新版由 AI 选择片段编号，程序回填原文，减少抄写和格式错误。它不会放宽事实正确性的要求。</p><label>声明的修改假设<textarea v-model="hypothesis" rows="3" /></label><label>补充判定提示词<textarea v-model="addendum" rows="3" placeholder="只调整判定逻辑；不输入保留题及其表现。" /></label><div v-if="variant==='J3'"><p>示例须已有独立人工参照，且来自校准集：</p><label v-for="s in state.dataset.samples.filter(s=>s.partition==='CALIBRATION')" :key="s.sample_id" class="check"><input v-model="exampleIds" type="checkbox" :value="s.sample_id" />{{s.question}}</label></div><p class="muted">本次负责评分的模型：{{work.state.session?.configuration?.judge_provider_configuration?.model||work.state.session?.configuration?.role_overrides?.judge?.model||work.state.session?.configuration?.model||'未连接'}}。原文引用会由程序核对；引用存在不代表判断正确。</p><button class="primary" :disabled="!sessionReady||!!state.validation||!hypothesis.trim()" @click="createProtocol">保存评分方法版本</button><EvidenceDetails v-if="state.protocol" :data="state.protocol" title="完整协议快照与声明差异" /></section>
      <section class="panel"><h2>只重评校准集回答</h2><label>选择协议<select v-model="protocolId"><option value="">选择已冻结版本</option><option v-for="p in protocols" :key="p.protocol_id" :value="p.protocol_id">{{p.name}} · {{p.protocol_id.slice(0,8)}}</option></select></label><div class="two-column"><label>独立评分重复次数<input v-model.number="repetitions" type="number" min="1" max="5" /></label><label>请求预算上限<input v-model.number="budget" type="number" min="1" max="500" /></label></div><p class="note">{{calibrationCount}} 份固定回答 × 1 个协议 × {{repetitions}} 次 = {{pendingBudget}} 次 AI 评分请求。预算 {{budget}}；不自动重试。usage 和费用不可得时显示未知。不会重新生成 Agent 回答。</p><button class="primary" :disabled="!sessionReady||!protocolId||budget<pendingBudget||!calibrationCount||!!state.validation" @click="runJudge">开始给固定回答评分</button><p v-if="state.pendingRun" class="muted">存在待确认请求。重提相同参数会复用请求 ID，不重复启动收费任务。</p></section>
      <section v-if="state.step===6" class="panel"><h2>配对版本比较</h2><div class="two-column"><label>基线运行<select v-model="baselineId"><option value="">选择运行</option><option v-for="r in runs.filter(r=>r.partition==='CALIBRATION')" :key="r.run_id" :value="r.run_id">{{protocols.find(p=>p.protocol_id===r.protocol_id)?.name}} · {{r.run_id.slice(0,8)}} · {{labelFor(r.status)}}</option></select></label><label>候选运行<select v-model="candidateId"><option value="">选择运行</option><option v-for="r in runs.filter(r=>r.partition==='CALIBRATION')" :key="r.run_id" :value="r.run_id">{{protocols.find(p=>p.protocol_id===r.protocol_id)?.name}} · {{r.run_id.slice(0,8)}} · {{labelFor(r.status)}}</option></select></label></div><button class="primary" :disabled="!baselineId||!candidateId||baselineId===candidateId" @click="cal.compare(baselineId,candidateId)">保存配对对照</button><template v-if="state.comparison"><p class="note">{{state.comparison.comparable?'冻结条件可比较':'不可按同口径比较'}} · {{state.comparison.reasons.join(' · ')}} · {{state.comparison.single_component_change?'一个组成部分改变':'多项协议变更'}}。单轮差异不证明因果。</p><div class="two-column"><section><h3>基线</h3><CalibrationMetrics :metrics="state.comparison.metrics_before" @inspect="inspected=$event" /></section><section><h3>候选</h3><CalibrationMetrics :metrics="state.comparison.metrics_after" @inspect="inspected=$event" /></section></div><EvidenceDetails :data="state.comparison.protocol_differences" title="实际协议差异" /><button class="secondary" @click="cal.go(7)">选择候选，进入保留验证 →</button></template></section></template>
    </template>
    <section v-else-if="state.step===5" class="panel"><h2>分歧与逐项证据</h2><label>标注者／查看者<input v-model="state.actor" /></label><label>已完成运行<select v-model="runId" @change="cal.act('读取已标注样本的机评',()=>cal.loadRun(runId))"><option value="">选择运行</option><option v-for="r in runs" :key="r.run_id" :value="r.run_id">{{labelFor(r.partition)}} · {{r.run_id.slice(0,8)}} · {{labelFor(r.status)}}</option></select></label><template v-if="state.run"><p class="note">尚未由此标注者提交的 {{state.run.hidden_sample_count}} 个样本隐藏机评。查看结果会记录该标注者的曝光。</p><CalibrationMetrics :metrics="state.run.metrics" @inspect="inspect" /><p>人工裁决前二元一致率：{{state.run.human_agreement.binary_agreement_before_adjudication.numerator}} / {{state.run.human_agreement.binary_agreement_before_adjudication.denominator}}</p></template><button class="secondary" @click="cal.go(6)">记录问题，修改评分方法 →</button></section>
    <section v-else-if="state.step===7" class="panel"><h2>候选锁定与保留验证</h2><p>候选锁定前不运行或展示逐题保留机评。标注可提前完成；锁定将冻结人工参照。解封后，该保留集不能再次承担独立验证。</p><p v-if="!ready" class="empty">先准备样本与标准。</p><template v-else><div v-if="!state.validation"><div class="two-column"><label>预先指定基线<select v-model="baseProtocol"><option value="">选择协议</option><option v-for="p in protocols" :key="p.protocol_id" :value="p.protocol_id">{{p.name}}</option></select></label><label>候选版本<select v-model="candidateProtocol"><option value="">选择协议</option><option v-for="p in protocols" :key="p.protocol_id" :value="p.protocol_id">{{p.name}}</option></select></label><label>重复次数<input v-model.number="validationRepetitions" type="number" min="1" max="5" /></label><label>总请求预算<input v-model.number="validationBudget" type="number" min="1" max="500" /></label></div><label>选定候选的理由与取舍<textarea v-model="validationReason" rows="3" /></label><p class="note">{{holdoutCount}} 份保留回答 × 2 个协议 × {{validationRepetitions}} 次 = {{finalBudget}} 次请求。总上限 {{validationBudget}}；不自动重试。</p><button class="primary" :disabled="!baseProtocol||!candidateProtocol||baseProtocol===candidateProtocol||!validationReason.trim()||!holdoutCount||validationBudget<finalBudget" @click="cal.lock({baseline_protocol_id:baseProtocol,candidate_protocol_id:candidateProtocol,reason:validationReason,repetitions:validationRepetitions,request_budget:validationBudget})">锁定版本、参照与预算</button></div><template v-else><p class="note">验证状态：{{state.validation.status}} · 基线 {{state.validation.baseline_protocol_id.slice(0,8)}} · 候选 {{state.validation.candidate_protocol_id.slice(0,8)}} · 解封 {{state.validation.released_at||'尚未解封'}}</p><div v-if="state.validation.status==='LOCKED'"><div class="two-column"><label>基线模型会话 ID<input v-model="baselineSession" /></label><label>候选模型会话 ID<input v-model="candidateSession" /></label></div><p class="muted">会话的模型与推理配置须与协议一致。凭据保留在已有会话的内存中。</p><button class="primary" :disabled="!baselineSession||!candidateSession" @click="cal.validate(baselineSession,candidateSession)">执行最终保留对照并解封结果</button></div><p v-if="state.validation.status==='FAILED'" class="note warning">最终采集失败。失败与缺失仍保留，不能宣称通过验证。</p><button v-if="state.validation.comparison_id" class="secondary" @click="cal.act('读取已解封对照',async()=>{state.comparison=await api.get(`/calibration/comparisons/${state.validation.comparison_id}?actor=${encodeURIComponent(state.actor)}`);cal.go(8)})">查看验证依据并保存结论 →</button></template></template></section>
    <section v-else-if="state.step===8" class="panel"><h2>保存采用或不采用的结论</h2><p v-if="!state.comparison" class="empty">先保存校准集对照，或完成最终保留验证。</p><template v-else><p class="note">当前对照 {{state.comparison.comparison_id.slice(0,8)}} · {{state.comparison.metrics_before.sample_count}} 份回答。{{state.validation?.comparison_id===state.comparison.comparison_id?'最终保留对照':'校准集对照，研究仍待保留验证'}}。</p><div class="two-column"><section><h3>基线</h3><CalibrationMetrics :metrics="state.comparison.metrics_before" @inspect="inspect" /></section><section><h3>候选</h3><CalibrationMetrics :metrics="state.comparison.metrics_after" @inspect="inspect" /></section></div><label>决策<select v-model="decision"><option value="KEEP_BASELINE">保留原版 / 不采用</option><option value="REVISE">继续调整</option><option value="ADOPT" :disabled="state.validation?.comparison_id!==state.comparison.comparison_id">采用候选</option></select></label><label>理由与证据局限<textarea v-model="conclusionReason" rows="4" /></label><label class="check"><input v-model="conclusionConfirmed" type="checkbox" />这是本人的采用判断。研究状态取决于真实独立人工参照与完整验证；没有改进也可以不采用。</label><button class="primary" :disabled="!conclusionReason.trim()||!conclusionConfirmed" @click="cal.conclude({decision,reason:conclusionReason})">保存结论与冻结报告</button></template><div v-for="c in state.history.conclusions.filter(c=>c.dataset_id===state.dataset?.dataset_id)" :key="c.conclusion_id" class="cal-source"><strong>{{labelFor(c.decision)}} · {{c.research_status==='PENDING'?'研究待完成':labelFor(c.research_status)}}</strong><p>{{c.reason}}</p><button class="secondary" @click="exportReport(c.conclusion_id)">导出 Markdown + JSON</button></div></section>
    <CalibrationDataRepair v-if="state.step===6&&state.dataset" /><CalibrationIssues v-if="state.step===9" />
    <section v-if="detailSample&&[5,6,8].includes(state.step)" class="panel"><div class="section-heading"><h2>逐题下钻 · {{detailSample.question}}</h2><button class="text-button" @click="inspected=''">关闭</button></div><p class="cal-answer">{{detailSample.answer}}</p><div class="two-column"><div><h3>冻结检索证据</h3><p v-for="e in detailSample.retrieved_evidence" :key="e.evidence_id">{{e.evidence_id}}：{{e.text}}</p></div><div><h3>参考政策快照</h3><p v-for="e in detailSample.reference_policy" :key="e.evidence_id">{{e.evidence_id}}：{{e.text}}</p></div></div><template v-for="r in detailResults" :key="r.repetition"><h3>重复 {{r.repetition}} · {{labelFor(r.status)}} · {{labelFor(r.judgment?.verdict||r.error)}}</h3><div v-for="(d,key) in r.judgment?.dimensions" :key="key" class="cal-source"><strong>{{labels[key]}} · {{d.score}}</strong><p>{{d.reason}}</p><p v-for="(quote,index) in d.answer_quotes" :key="index">回答：“{{quote}}”</p><p v-for="(cite,index) in d.citations" :key="index">{{cite.scope}} / {{cite.evidence_id}}：“{{cite.quote}}”</p></div><p>{{r.judgment?.reason}}</p></template><EvidenceDetails v-if="state.run?.references[inspected]" :data="state.run.references[inspected]" title="独立人工参照与裁决来源" /><p v-if="!detailResults.length" class="muted">请在分歧页选择对应运行，以查看原始逐维机评。当前对照保存了配对状态与完整报告证据。</p><template v-if="detailResults.length"><button class="primary" @click="trackIssue">建立问题修复记录 →</button><h3>记录原因假设 · 可多选</h3><label v-for="(label,key) in causeLabels" :key="key" class="check"><input v-model="hypothesisCauses" type="checkbox" :value="key" />{{label}}</label><label>具体分歧与验证办法<textarea v-model="hypothesisReason" rows="3" /></label><p class="muted">这些标签是待核验假设，不能单凭标签声称因果成立。</p><button class="primary" :disabled="!hypothesisCauses.length||!hypothesisReason.trim()" @click="cal.act('保存原因假设',()=>api.post('/calibration/hypotheses',{dataset_id:state.dataset.dataset_id,sample_id:inspected,run_id:state.run.run.run_id,actor:state.actor,causes:hypothesisCauses,reason:hypothesisReason}))">保存假设</button></template></section>
    </fieldset>
  </div>
</template>
